const {electron}=require('./test-app.cjs'),close=require('./close-test-app.cjs'),fs=require('fs'),path=require('path'),assert=require('assert/strict');
const formal=process.argv.includes('--formal'),root=path.resolve('evidence/category-restore-20261023/ui-'+Date.now());fs.mkdirSync(root,{recursive:true});
(async()=>{let app;const report={root,formal};try{const env={...process.env};delete env.ELECTRON_RUN_AS_NODE;if(formal)delete env.YIMU_DATA_DIR;else env.YIMU_DATA_DIR=path.join(root,'empty-library');app=await electron.launch({...(formal?{executablePath:path.join(process.env.LOCALAPPDATA,'Programs/YimuCraft/YimuCraft.exe'),args:[]}:{args:['.']}),env});const page=await app.firstWindow();await page.waitForFunction(()=>document.querySelector('#status')?.textContent.startsWith('就绪'));
if(formal){const recovered=JSON.parse(fs.readFileSync('evidence/category-restore-20261023/run-1792771266146/report.json','utf8'));report.categories=[];for(const c of recovered.mappings){const r=await page.evaluate(id=>window.yimu.command('query',{collection:id,limit:1}),c.id);report.categories.push({name:c.name,count:r.total});assert.ok(r.total>0);}const stats=await page.evaluate(()=>window.yimu.command('stats'));assert.equal(stats.total,65586);assert.ok(!stats.collections.some(c=>c.name==='526种AE内置插件效果可视化预设'));assert.ok(stats.folders.some(f=>f.folder.includes('526种AE')));const utility=recovered.mappings.find(c=>c.name.startsWith('实用工具'));await page.evaluate(async id=>{state.collection=id;await refresh();renderCollections();},utility.id);await page.screenshot({path:path.join(root,'restored-categories.png')});await page.evaluate(async()=>{state.collection=null;document.querySelector('#search').value='__yimu_absent_logo_validation__';await refresh();});}
await page.locator('#empty').waitFor({state:'visible'});report.logo=await page.locator('#empty .empty-logo').evaluate(i=>({src:i.getAttribute('src'),loaded:i.complete&&i.naturalWidth>0,width:i.getBoundingClientRect().width,height:i.getBoundingClientRect().height}));assert.equal(report.logo.src,'brand.svg');assert.ok(report.logo.loaded);await page.screenshot({path:path.join(root,'logo.png')});report.passed=true;
}catch(e){report.passed=false;report.error=e.stack;process.exitCode=1;}finally{await close(app);fs.writeFileSync(path.join(root,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report));}})();
